-- ═══════════════════════════════════════════════════════════════════
-- Row-level security: every bible table is workspace-scoped
-- ═══════════════════════════════════════════════════════════════════
--
-- The same set as every scoped table (docs/rls-workspace-isolation.md): RLS
-- enabled and FORCED, ONE `workspace_isolation` policy with USING and WITH
-- CHECK on the same predicate, and `superuser_bypass` for every role but
-- app_user. tests/guards/rls-migration-coverage.test.ts compares these
-- statements exactly; tests/integration/rls-coverage.test.ts compares what
-- PostgreSQL stored and proves they isolate. app_user's table grants come from
-- the default privileges the 0.3 migration set.

ALTER TABLE "Book" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "Book" FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS workspace_isolation ON "Book";
CREATE POLICY workspace_isolation ON "Book"
    USING ("workspaceId" = current_setting('app.workspace_id', true)::text)
    WITH CHECK ("workspaceId" = current_setting('app.workspace_id', true)::text);
DROP POLICY IF EXISTS superuser_bypass ON "Book";
CREATE POLICY superuser_bypass ON "Book"
    USING (current_setting('role') != 'app_user');

ALTER TABLE "BibleElement" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "BibleElement" FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS workspace_isolation ON "BibleElement";
CREATE POLICY workspace_isolation ON "BibleElement"
    USING ("workspaceId" = current_setting('app.workspace_id', true)::text)
    WITH CHECK ("workspaceId" = current_setting('app.workspace_id', true)::text);
DROP POLICY IF EXISTS superuser_bypass ON "BibleElement";
CREATE POLICY superuser_bypass ON "BibleElement"
    USING (current_setting('role') != 'app_user');

ALTER TABLE "BibleField" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "BibleField" FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS workspace_isolation ON "BibleField";
CREATE POLICY workspace_isolation ON "BibleField"
    USING ("workspaceId" = current_setting('app.workspace_id', true)::text)
    WITH CHECK ("workspaceId" = current_setting('app.workspace_id', true)::text);
DROP POLICY IF EXISTS superuser_bypass ON "BibleField";
CREATE POLICY superuser_bypass ON "BibleField"
    USING (current_setting('role') != 'app_user');

ALTER TABLE "BibleRelation" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "BibleRelation" FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS workspace_isolation ON "BibleRelation";
CREATE POLICY workspace_isolation ON "BibleRelation"
    USING ("workspaceId" = current_setting('app.workspace_id', true)::text)
    WITH CHECK ("workspaceId" = current_setting('app.workspace_id', true)::text);
DROP POLICY IF EXISTS superuser_bypass ON "BibleRelation";
CREATE POLICY superuser_bypass ON "BibleRelation"
    USING (current_setting('role') != 'app_user');

ALTER TABLE "BibleEntryVersion" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "BibleEntryVersion" FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS workspace_isolation ON "BibleEntryVersion";
CREATE POLICY workspace_isolation ON "BibleEntryVersion"
    USING ("workspaceId" = current_setting('app.workspace_id', true)::text)
    WITH CHECK ("workspaceId" = current_setting('app.workspace_id', true)::text);
DROP POLICY IF EXISTS superuser_bypass ON "BibleEntryVersion";
CREATE POLICY superuser_bypass ON "BibleEntryVersion"
    USING (current_setting('role') != 'app_user');

-- ═══════════════════════════════════════════════════════════════════
-- Shape the database holds whoever writes
-- ═══════════════════════════════════════════════════════════════════
--
-- Bounds on the readable columns only: an encrypted column's stored length is
-- the envelope's, so its bound lives in the usecase's schema
-- (src/app-layer/schemas/bible.ts).

ALTER TABLE "Book" ADD CONSTRAINT "Book_title_bounded"
    CHECK (char_length(btrim("title")) BETWEEN 1 AND 200 AND "title" = btrim("title"));
ALTER TABLE "Book" ADD CONSTRAINT "Book_targetLength_positive"
    CHECK ("targetLength" IS NULL OR "targetLength" BETWEEN 1 AND 5000000);

ALTER TABLE "BibleElement" ADD CONSTRAINT "BibleElement_name_bounded"
    CHECK (char_length("name") BETWEEN 1 AND 120 AND "name" = btrim("name"));
ALTER TABLE "BibleElement" ADD CONSTRAINT "BibleElement_slug_shape"
    CHECK (char_length("slug") <= 80 AND "slug" ~ '^[a-z0-9]+(-[a-z0-9]+)*$');
-- A CUSTOM element carries the author's own label; no other kind carries one.
ALTER TABLE "BibleElement" ADD CONSTRAINT "BibleElement_customLabel_iff_custom"
    CHECK (
        ("kind" = 'CUSTOM' AND "customLabel" IS NOT NULL
            AND char_length("customLabel") BETWEEN 1 AND 60 AND "customLabel" = btrim("customLabel"))
        OR ("kind" <> 'CUSTOM' AND "customLabel" IS NULL)
    );

ALTER TABLE "BibleField" ADD CONSTRAINT "BibleField_key_shape"
    CHECK (char_length("key") <= 32 AND "key" ~ '^[a-z][a-z0-9]*(_[a-z0-9]+)*$');
ALTER TABLE "BibleField" ADD CONSTRAINT "BibleField_order_positive" CHECK ("order" >= 1);

ALTER TABLE "BibleRelation" ADD CONSTRAINT "BibleRelation_not_to_itself"
    CHECK ("fromElementId" <> "toElementId");
ALTER TABLE "BibleRelation" ADD CONSTRAINT "BibleRelation_type_shape"
    CHECK (char_length("type") <= 32 AND "type" ~ '^[a-z][a-z0-9]*(_[a-z0-9]+)*$');

ALTER TABLE "BibleEntryVersion" ADD CONSTRAINT "BibleEntryVersion_versionNumber_positive"
    CHECK ("versionNumber" >= 1);
ALTER TABLE "BibleEntryVersion" ADD CONSTRAINT "BibleEntryVersion_restoredFrom_earlier"
    CHECK ("restoredFromVersion" IS NULL OR ("restoredFromVersion" >= 1 AND "restoredFromVersion" < "versionNumber"));

-- ═══════════════════════════════════════════════════════════════════
-- BibleEntryVersion is append-only
-- ═══════════════════════════════════════════════════════════════════
--
-- History is the author's record of what the bible said and when (roadmap
-- rule 1: every accepted change is a new version). Nothing rewrites it:
--
--   app_user    may read and insert; it holds no UPDATE, DELETE or TRUNCATE.
--   every role  the trigger below refuses UPDATE and DELETE (P0001, message
--               prefix BIBLE_VERSION_APPEND_ONLY) and TRUNCATE, for the owner
--               and a superuser too, as the audit log's does.
--
-- Two writes pass, both made by the database's own referential actions:
--
--   * The DELETE its book's cascade makes (a book deleted on its own, or with
--     its workspace). By the time the trigger runs for those rows the book row
--     is already gone, which is what the check reads: a version of a book that
--     still exists is never deleted. (The last-OWNER guard reads its
--     workspace the same way.)
--   * The UPDATE that clears `authorId` when that person's account is deleted
--     (ON DELETE SET NULL): only `authorId` changes, from a user who no longer
--     exists to NULL. The version, and what it says, stay.
--
-- Referential actions run as the table's owner, so the cascade does not need
-- the DELETE grant app_user lacks. Keep the function VOLATILE: each check
-- reads a fresh snapshot.

REVOKE UPDATE, DELETE, TRUNCATE ON TABLE "BibleEntryVersion" FROM app_user;

CREATE OR REPLACE FUNCTION bible_entry_version_append_only() RETURNS trigger
LANGUAGE plpgsql
VOLATILE
AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        IF NOT EXISTS (SELECT 1 FROM "Book" WHERE "id" = OLD."bookId") THEN
            RETURN OLD;
        END IF;
    ELSIF TG_OP = 'UPDATE' THEN
        IF OLD."authorId" IS NOT NULL
           AND NEW."authorId" IS NULL
           AND (to_jsonb(NEW) - 'authorId') = (to_jsonb(OLD) - 'authorId')
           AND NOT EXISTS (SELECT 1 FROM "User" WHERE "id" = OLD."authorId") THEN
            RETURN NEW;
        END IF;
    END IF;
    RAISE EXCEPTION 'BIBLE_VERSION_APPEND_ONLY: % of BibleEntryVersion refused', TG_OP
        USING ERRCODE = 'P0001';
END;
$$;

DROP TRIGGER IF EXISTS bible_entry_version_no_update_delete ON "BibleEntryVersion";
CREATE TRIGGER bible_entry_version_no_update_delete
    BEFORE UPDATE OR DELETE ON "BibleEntryVersion"
    FOR EACH ROW EXECUTE FUNCTION bible_entry_version_append_only();

DROP TRIGGER IF EXISTS bible_entry_version_no_truncate ON "BibleEntryVersion";
CREATE TRIGGER bible_entry_version_no_truncate
    BEFORE TRUNCATE ON "BibleEntryVersion"
    FOR EACH STATEMENT EXECUTE FUNCTION bible_entry_version_append_only();
